// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Enumeration;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.junit.jupiter.api.Test;

/**
 * Cross-cutting census checks for the GH-6193 extension functions on top of {@link LmdbNativeExpressionCensusTest}
 * (which already fails when a registered function has no census entry at all): every function class listed in the
 * {@link Function} SPI service files appears in {@link LmdbNativeExpressionCensus} <em>exactly once</em>, the census
 * carries no stale entries for functions that are no longer registered, and every extension-function family is marked
 * {@code GENERIC} so the native LMDB engine falls back to generic evaluation instead of compiling it.
 * <p>
 * The "exactly once" and "no stale entry" checks read the census source file, because the census map is private and
 * {@code Map.ofEntries} would reject a duplicate key with an exception before any assertion could name the offender.
 */
public class LmdbExtensionFunctionCensusTest {

	private static final String FUNCTION_SERVICE = "META-INF/services/" + Function.class.getName();
	private static final String FUNCTION_PACKAGE = "org.eclipse.rdf4j.query.algebra.evaluation.function.";
	private static final Path CENSUS_SOURCE = Paths.get(System.getProperty("basedir", "."), "src", "main", "java",
			"org", "eclipse", "rdf4j", "sail", "lmdb", "evaluation", "LmdbNativeExpressionCensus.java");
	private static final Pattern CENSUS_ENTRY = Pattern
			.compile("Map\\.entry\\(FUNCTION_PACKAGE \\+ \"([^\"]+)\", Kind\\.([A-Z_]+)\\)");

	/** Sub-packages of the GH-6193 extension-function families (window functions included). */
	private static final List<String> EXTENSION_PACKAGES = List.of("math.", "string.ext.", "datetime.ext.",
			"bitwise.", "encoding.", "misc.", "text.", "array.", "json.", "window.");

	@Test
	public void everyRegisteredFunctionAppearsExactlyOnceInTheCensus() throws Exception {
		Set<String> registered = registeredFunctionImplementations();
		assertThat(registered).as("SPI scan sanity").hasSizeGreaterThan(150);
		Map<String, Integer> occurrences = censusSourceOccurrences();
		List<String> problems = new ArrayList<>();
		for (String implementation : registered) {
			if (LmdbNativeExpressionCensus.classifyFunction(implementation) == null) {
				problems.add(implementation + ": no census entry");
			}
			int count = occurrences.getOrDefault(implementation, 0);
			if (count != 1) {
				problems.add(implementation + ": " + count + " census source entries");
			}
		}
		assertThat(problems).as("every SPI-registered function must have exactly one census entry").isEmpty();
	}

	@Test
	public void censusHasNoStaleFunctionEntries() throws Exception {
		Set<String> registered = registeredFunctionImplementations();
		List<String> stale = new ArrayList<>();
		for (String censusEntry : censusSourceOccurrences().keySet()) {
			if (!registered.contains(censusEntry)) {
				stale.add(censusEntry);
			}
		}
		assertThat(stale).as("census entries whose function is no longer in any SPI service file").isEmpty();
	}

	@Test
	public void extensionFunctionFamiliesFallBackToGenericEvaluation() throws Exception {
		List<String> extension = new ArrayList<>();
		for (String implementation : registeredFunctionImplementations()) {
			String local = implementation.substring(FUNCTION_PACKAGE.length());
			for (String family : EXTENSION_PACKAGES) {
				if (local.startsWith(family)) {
					extension.add(implementation);
				}
			}
		}
		assertThat(extension).as("extension family scan sanity").hasSizeGreaterThan(100);
		List<String> notGeneric = new ArrayList<>();
		for (String implementation : extension) {
			if (LmdbNativeExpressionCensus
					.classifyFunction(implementation) != LmdbNativeExpressionCensus.Kind.GENERIC) {
				notGeneric.add(implementation + " -> " + LmdbNativeExpressionCensus.classifyFunction(implementation));
			}
		}
		assertThat(notGeneric)
				.as("extension functions have no native LMDB compiler and must be census-marked GENERIC "
						+ "(update this pin deliberately when one is promoted)")
				.isEmpty();
	}

	@Test
	public void unregisteredFunctionClassIsUnclassified() {
		// the failure path of the census: a class that is not in the inventory yields null, which the census tests
		// above turn into an assertion failure as soon as such a class shows up in a service file
		assertThat(LmdbNativeExpressionCensus.classifyFunction(FUNCTION_PACKAGE + "misc.NotARegisteredFunction"))
				.isNull();
		assertThat(LmdbNativeExpressionCensus.classifyFunction(FUNCTION_PACKAGE + "misc.NullIf"))
				.isEqualTo(LmdbNativeExpressionCensus.Kind.GENERIC);
	}

	private static Map<String, Integer> censusSourceOccurrences() throws Exception {
		assertThat(CENSUS_SOURCE).as("census source file").exists();
		Map<String, Integer> occurrences = new LinkedHashMap<>();
		Matcher matcher = CENSUS_ENTRY.matcher(Files.readString(CENSUS_SOURCE, StandardCharsets.UTF_8));
		while (matcher.find()) {
			occurrences.merge(FUNCTION_PACKAGE + matcher.group(1), 1, Integer::sum);
		}
		assertThat(occurrences).as("census source scan sanity").hasSizeGreaterThan(150);
		return occurrences;
	}

	private static Set<String> registeredFunctionImplementations() throws Exception {
		Set<String> implementations = new LinkedHashSet<>();
		Enumeration<URL> resources = Function.class.getClassLoader().getResources(FUNCTION_SERVICE);
		while (resources.hasMoreElements()) {
			URL resource = resources.nextElement();
			try (BufferedReader reader = new BufferedReader(
					new InputStreamReader(resource.openStream(), StandardCharsets.UTF_8))) {
				String line;
				while ((line = reader.readLine()) != null) {
					String name = line.trim();
					int comment = name.indexOf('#');
					if (comment >= 0) {
						name = name.substring(0, comment).trim();
					}
					if (!name.isEmpty()) {
						implementations.add(name);
					}
				}
			}
		}
		return implementations;
	}
}
